package io.github.diodeme.ji.host;

import java.security.MessageDigest;
import java.security.SecureRandom;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.Base64;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

/** One-use loopback launch token exchange. Only token digests are retained. */
public final class LocalTokenService {
    private static final Duration TOKEN_LIFETIME = Duration.ofMinutes(2);
    private final SecureRandom random;
    private final Clock clock;
    private final Map<String, Instant> tokenDigests = new ConcurrentHashMap<>();

    public LocalTokenService(SecureRandom random, Clock clock) {
        this.random = random;
        this.clock = clock;
    }

    public String issue() {
        byte[] bytes = new byte[32];
        random.nextBytes(bytes);
        String token = [REDACTED_CREDENTIAL]
        tokenDigests.put(digest(token), clock.instant().plus(TOKEN_LIFETIME));
        return token;
    }

    public Optional<String> exchange(String token, boolean loopbackRequest) {
        if (!loopbackRequest || token =[REDACTED_CREDENTIAL] null) return Optional.empty();
        Instant expiry = tokenDigests.remove(digest(token));
        if (expiry == null || !clock.instant().isBefore(expiry)) return Optional.empty();
        byte[] bytes = new byte[32];
        random.nextBytes(bytes);
        return Optional.of(Base64.getUrlEncoder().withoutPadding().encodeToString(bytes));
    }

    private static String digest(String value) {
        try {
            byte[] hash = MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            return java.util.HexFormat.of().formatHex(hash);
        } catch (java.security.NoSuchAlgorithmException exception) {
            throw new IllegalStateException(exception);
        }
    }
}
